  int checks=0;void Check(bool v,string why){if(!v)throw new Exception(why);checks++;}void Refuse(Action a,string why){try{a();}catch(InvalidDataException){checks++;return;}throw new Exception("Accepted "+why);}var source=lib.Get("alpineridge");var native=lib.Disc.Exe;var host=new UniversalLevelData(compiled.CopyLevelData());var overlay=new UniversalOverlay(compiled.CopyOverlay(),UniversalExeBindings.Read(compiled.CopyExecutable(),20));int[] delta=[-65536,-32768,-12288];
