  foreach(var p in placements)foreach(int offset in new[]{0x36,0x3C,0x3E,0x40,0x48,0x53}){var edited=placements.Select(x=>x.SourceRowIndex==p.SourceRowIndex?x with{RowByteOverrides=new Dictionary<int,byte>{{offset,0xFD}}}:x).ToArray();Refuse(()=>compiled.Compose(lib,edited),"actual Compose override after source certificate");}var valid=placements.Select(p=>p with{RowByteOverrides=new Dictionary<int,byte>{{0x4A,255}}}).ToArray();Check(compiled.Compose(lib,valid).NewRowIndices.Count==2,"ordinary unrestricted visibility override remains allowed");
