  var crowded=new UniversalLevelData(NativeFreshPlacementArena.Prepare(compiled.CopyLevelData(),2));var genuine=source.Data.Package(0x10E);var used=crowded.Registrations().Select(r=>r.ClassId).ToHashSet();foreach(int c in Enumerable.Range(100,160).Where(c=>!used.Contains(c)).Take(40))crowded.AppendModel(c,genuine);try{_=UniversalMobyComposer.Compose(compiled.Target,crowded.Bytes,compiled.CopyOverlay(),compiled.CopyExecutable(),lib.Get,lib.SharedClasses,protectedRanges,placements,sharedModelPackage:lib.SharedModelPackage,playerAnimationSource:lib.PlayerAnimations,persistentNativePrefixRows:135,nativeDestinationOwner:overlay,nativeOriginalExecutable:native);throw new Exception("Accepted real final RAM overflow");}catch(UniversalBudgetException e){Check(e.Budget.FinalHeadroom<0,"actual final RAM capacity owner");}
